```js
// Resolve one ball/brick overlap: bounce off the correct face, push the ball
// out, kill the brick. Returns true if a bounce was applied.
function resolveBrick(state, ball, brick) {
  // penetration beyond each face (distance the ball must travel to clear it)
  const fromTop = ball.y + ball.r - brick.y;
  const fromBottom = brick.y + brick.h - (ball.y - ball.r);
  const fromLeft = ball.x + ball.r - brick.x;
  const fromRight = brick.x + brick.w - (ball.x - ball.r);
  const penY = Math.min(fromTop, fromBottom);
  const penX = Math.min(fromLeft, fromRight);

  let hitY = false; // flip vy?
  let hitX = false; // flip vx?

  if (penY < penX) {
    // top/bottom face
    if (fromTop < fromBottom) {
      ball.y = brick.y - ball.r;
      if (ball.vy > 0) { ball.vy = -ball.vy; hitY = true; }
    } else {
      ball.y = brick.y + brick.h + ball.r;
      if (ball.vy < 0) { ball.vy = -ball.vy; hitY = true; }
    }
  } else if (penX < penY) {
    // left/right face
    if (fromLeft < fromRight) {
      ball.x = brick.x - ball.r;
      if (ball.vx > 0) { ball.vx = -ball.vx; hitX = true; }
    } else {
      ball.x = brick.x + brick.w + ball.r;
      if (ball.vx < 0) { ball.vx = -ball.vx; hitX = true; }
    }
  } else {
    // corner: flip both
    if (fromTop < fromBottom) { ball.y = brick.y - ball.r; if (ball.vy > 0) ball.vy = -ball.vy; }
    else { ball.y = brick.y + brick.h + ball.r; if (ball.vy < 0) ball.vy = -ball.vy; }
    if (fromLeft < fromRight) { ball.x = brick.x - ball.r; if (ball.vx > 0) ball.vx = -ball.vx; }
    else { ball.x = brick.x + brick.w + ball.r; if (ball.vx < 0) ball.vx = -ball.vx; }
  }

  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
  return hitX || hitY;
}
```

