```js
export function step(state, dt) {
  const { ball, paddle } = state;

  // Sub-stepped motion so the ball cannot tunnel through a brick row at high
  // speed (see #1): each sub-step moves less than the thickness of a brick
  // plus the ball's diameter, so the overlap is never skipped.
  const MAX_SUB_STEP = 12;
  const dist = Math.hypot(ball.vx, ball.vy) * dt;
  const subSteps = Math.max(1, Math.ceil(dist / MAX_SUB_STEP));
  const subDt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Bricks: resolve every overlap in this sub-step exactly once (a seam
    // straddles two bricks; the bounce must not be applied twice).
    const hits = [];
    for (const brick of state.bricks) {
      if (brick.alive && collides(ball, brick)) hits.push(brick);
    }
    if (hits.length > 0) {
      // The brick the ball is deepest inside decides the face to bounce off.
      let target = hits[0];
      let bestPen = penetration(target, ball);
      for (let j = 1; j < hits.length; j++) {
        const pen = penetration(hits[j], ball);
        if (pen < bestPen) { target = hits[j]; bestPen = pen; }
      }
      resolveBrick(state, ball, target);
      for (const brick of hits) {
        if (brick !== target && brick.alive) {
          brick.alive = false;
          state.combo += 1;
          state.score += scoreForBrick(brick, state.combo);
        }
      }
    }
    ...walls...
  }
  ...lost check...
}
```

