```js
// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Bricks are 20 px tall and the ball 14 px across: a fast ball can cross a
// whole brick between two frames (35.5 px at level 6 with a 50 ms frame), so
// the move is split into sub-steps of at most 12 px. The overlap is then
// detected on every sub-step and can no longer be skipped (see #1).
const MAX_SUB_STEP = 12;

// Smallest distance from the ball to a face of the brick: the axis with the
// smaller penetration is the face that was hit (see #1).
function penetrationDepth(ball, brick) {
  const penX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const penY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
  return Math.min(penX, penY);
}

// Resolves ONE overlap: bounces off the face with the smallest penetration,
// pushes the ball out of the brick and breaks it. A velocity component is only
// flipped when it actually heads INTO the brick — a ball already moving away is
// just pushed out, which keeps the resolution stable at seams and corners.
// Returns nothing: mutates `state` (ball, bricks, combo, score).
function resolveBrick(state, ball, brick) {
  const fromTop = ball.y + ball.r - brick.y;
  const fromBottom = brick.y + brick.h - (ball.y - ball.r);
  const fromLeft = ball.x + ball.r - brick.x;
  const fromRight = brick.x + brick.w - (ball.x - ball.r);
  const penY = Math.min(fromTop, fromBottom);
  const penX = Math.min(fromLeft, fromRight);

  if (penY < penX) {
    // top or bottom face
    if (fromTop < fromBottom) {
      ball.y = brick.y - ball.r;
      if (ball.vy > 0) ball.vy = -ball.vy;
    } else {
      ball.y = brick.y + brick.h + ball.r;
      if (ball.vy < 0) ball.vy = -ball.vy;
    }
  } else if (penX < penY) {
    // left or right face
    if (fromLeft < fromRight) {
      ball.x = brick.x - ball.r;
      if (ball.vx > 0) ball.vx = -ball.vx;
    } else {
      ball.x = brick.x + brick.w + ball.r;
      if (ball.vx < 0) ball.vx = -ball.vx;
    }
  } else {
    // corner: diagonal hit, flip both components
    if (fromTop < fromBottom) {
      ball.y = brick.y - ball.r;
      if (ball.vy > 0) ball.vy = -ball.vy;
    } else {
      ball.y = brick.y + brick.h + ball.r;
      if (ball.vy < 0) ball.vy = -ball.vy;
    }
    if (fromLeft < fromRight) {
      ball.x = brick.x - ball.r;
      if (ball.vx > 0) ball.vx = -ball.vx;
    } else {
      ball.x = brick.x + brick.w + ball.r;
      if (ball.vx < 0) ball.vx = -ball.vx;
    }
  }

  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// Checks every live brick once and breaks all of those the ball overlaps. The
// bounce itself is applied against a SINGLE brick — the one the ball is deepest
// inside. An 8 px seam is narrower than the ball, so the same hit can straddle
// two bricks; bouncing twice (vy = -vy twice) would cancel out and let the ball
// through (see #1).
function breakBricks(state) {
  const { ball } = state;
  const hits = state.bricks.filter((b) => b.alive && collides(ball, b));
  if (hits.length === 0) return;

  let target = hits[0];
  let depth = penetrationDepth(ball, target);
  for (let i = 1; i < hits.length; i++) {
    const d = penetrationDepth(ball, hits[i]);
    if (d < depth) {
      target = hits[i];
      depth = d;
    }
  }
  resolveBrick(state, ball, target);
  for (const brick of hits) {
    if (brick !== target && brick.alive) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks (movement is sub-stepped so a fast ball
// cannot tunnel through a brick, see #1).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const dist = Math.hypot(ball.vx, ball.vy) * dt;
  const subSteps = Math.max(1, Math.ceil(dist / MAX_SUB_STEP));
  const subDt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    breakBricks(state);

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}
```

