  assert.ok(state.ball.vx < 0, 'vx should flip leftward');
  assert.equal(state.ball.vy, 0, 'vy untouched on a side hit');
  assert.ok(state.ball.x + state.ball.r <= brick.x, 'ball pushed left of the brick');
  assert.equal(collides(state.ball, brick), false, 'no sticky overlap after bounce');
});

test('brick bounce: right face — vx flips right, ball pushed out', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  const c = centerOf(brick);
  state.ball = { x: brick.x + brick.w + BALL_R + 1, y: c.y, r: BALL_R, vx: -300, vy: 0 };

  step(state, 1 / 60);

  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx > 0, 'vx should flip rightward');
  assert.equal(state.ball.vy, 0);
  assert.ok(state.ball.x - state.ball.r >= brick.x + brick.w, 'ball pushed right of the brick');
});

test('brick bounce: corner — equal penetration flips BOTH components', () => {
  const state = createState(1);
  const brick = state.bricks[1]; // x 84..156, y 48..68
  // Start up-left of the corner; 5 px of motion gives equal pen on both axes.
  state.ball = { x: brick.x - BALL_R - 2, y: brick.y - BALL_R - 2, r: BALL_R, vx: 300, vy: 300 };

  step(state, 1 / 60);

  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'diagonal hit flips vx and vy');
  assert.equal(collides(state.ball, brick), false, 'pushed out of the corner');
});

test('brick bounce: seam — two bricks straddled, bounce applied exactly once', () => {
  const state = createState(1);
  const a = state.bricks[0]; // x 4..76
  const b = state.bricks[1]; // x 84..156 (8 px gap)
  const gap = (a.x + a.w + b.x) / 2; // 80: the ball (14 px) covers both edges
  state.ball = { x: gap, y: a.y - BALL_R - 1, r: BALL_R, vx: 100, vy: 300 };

  step(state, 1 / 60);

  assert.equal(a.alive, false, 'left brick broken');
  assert.equal(b.alive, false, 'right brick broken');
  assert.equal(state.ball.vx, -100, 'vx flipped exactly once (not twice)');
  assert.equal(state.ball.vy, 300, 'vy untouched');
});

test('brick bounce: tunnelling — fast ball must not skip a brick (level 6)', () => {
  const state = createState(6); // ballSpeed(6) = 710 px/s
  const brick = state.bricks[0];
  const c = centerOf(brick);
  // 710 * 0.05 = 35.5 px: more than a brick height + diameter (34 px).
  state.ball = { x: c.x, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: 710 };

  step(state, 0.05);

  assert.equal(brick.alive, false, 'ball must hit the brick, not jump over it');
  assert.ok(state.ball.vy < 0, 'ball bounces up after the sweep');
});

test('brick bounce: breaking scores with the combo', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = ballAbove(brick);

  step(state, 1 / 60);

  assert.equal(state.combo, 1);
  assert.equal(state.score, scoreForBrick(brick, 1));
});

