    const approaching = isApproaching(ball, pen);
    const depth = Math.min(pen.penX, pen.penY);
    if (approaching !== targetApproach) {
      // Approaching hits always beat grazing ones.
      if (approaching) {
        target = hits[i];
        targetPen = pen;
        targetApproach = true;
        targetDepth = depth;
