// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The face resolution lives in `resolveBrick()` (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Bricks are 20 px tall and the ball 14 px across, so a fast ball can cross a
// whole brick between two frames (35.5 px at level 6 with a 50 ms frame cap).
// The move is therefore split into sub-steps of at most 12 px: the overlap is
// tested on every sub-step and can no longer be skipped (anti-tunnelling, #1).
const MAX_SUB_STEP = 12;

// Penetration of the ball past each of the four faces of the brick.
function facePenetrations(ball, brick) {
  const fromTop = ball.y + ball.r - brick.y;
  const fromBottom = brick.y + brick.h - (ball.y - ball.r);
  const fromLeft = ball.x + ball.r - brick.x;
  const fromRight = brick.x + brick.w - (ball.x - ball.r);
  return { fromTop, fromBottom, fromLeft, fromRight };
}

// True when the ball is heading INTO the brick on its hit axis: a ball that
// merely grazes a brick while moving AWAY from it is not the brick to bounce
// off (it is only caught as a co-hit). Mirrors the flip guards in resolveBrick.
function isApproaching(ball, pen) {
  const penY = Math.min(pen.fromTop, pen.fromBottom);
  const penX = Math.min(pen.fromLeft, pen.fromRight);
  if (penY < penX) return pen.fromTop < pen.fromBottom ? ball.vy > 0 : ball.vy < 0;
  if (penX < penY) return pen.fromLeft < pen.fromRight ? ball.vx > 0 : ball.vx < 0;
  // Corner: approached as soon as either component heads into the brick.
  const yInto = pen.fromTop < pen.fromBottom ? ball.vy > 0 : ball.vy < 0;
  const xInto = pen.fromLeft < pen.fromRight ? ball.vx > 0 : ball.vx < 0;
  return yInto || xInto;
}

// Resolves ONE overlap: bounces off the face with the smallest penetration
// (corner = equal penetrations → flip both components), pushes the ball back
// OUT of the brick (so it cannot still overlap on the next frame and re-flip
// forever), then breaks the brick and scores it.
// A velocity component is only flipped when it actually heads INTO the brick:
// a ball already moving away is merely pushed out, which keeps the resolution
// stable at seams and corners.
function resolveBrick(state, ball, brick) {
  const pen = facePenetrations(ball, brick);
  const penY = Math.min(pen.fromTop, pen.fromBottom);
  const penX = Math.min(pen.fromLeft, pen.fromRight);

  if (penY < penX) {
    // Top or bottom face: flip vy, leave vx exactly as it was.
    if (pen.fromTop < pen.fromBottom) {
      ball.y = brick.y - ball.r;
      if (ball.vy > 0) ball.vy = -ball.vy;
    } else {
      ball.y = brick.y + brick.h + ball.r;
      if (ball.vy < 0) ball.vy = -ball.vy;
    }
  } else if (penX < penY) {
    // Left or right face: flip vx, leave vy exactly as it was.
    if (pen.fromLeft < pen.fromRight) {
      ball.x = brick.x - ball.r;
      if (ball.vx > 0) ball.vx = -ball.vx;
    } else {
      ball.x = brick.x + brick.w + ball.r;
      if (ball.vx < 0) ball.vx = -ball.vx;
    }
  } else {
    // Corner: equal penetrations = diagonal hit, flip both components.
    if (pen.fromTop < pen.fromBottom) {
      ball.y = brick.y - ball.r;
      if (ball.vy > 0) ball.vy = -ball.vy;
    } else {
      ball.y = brick.y + brick.h + ball.r;
      if (ball.vy < 0) ball.vy = -ball.vy;
    }
    if (pen.fromLeft < pen.fromRight) {
      ball.x = brick.x - ball.r;
      if (ball.vx > 0) ball.vx = -ball.vx;
    } else {
      ball.x = brick.x + brick.w + ball.r;
      if (ball.vx < 0) ball.vx = -ball.vx;
    }
  }

  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// Breaks every live brick the ball overlaps in this sub-step, but applies the
// bounce against a SINGLE brick: the one the ball is deepest inside AND
// heading into (see isApproaching). The grid gap is 8 px and the ball 14 px
// across, so one hit straddles two bricks at every seam — resolving both
// would flip vx twice and cancel out (see #1).
function breakBricks(state) {
  const { ball } = state;
  const hits = state.bricks.filter((brick) => brick.alive && collides(ball, brick));
  if (hits.length === 0) return;

  let target = hits[0];
  let targetPen = facePenetrations(ball, target);
  let targetApproach = isApproaching(ball, targetPen);
  let targetDepth = Math.min(
    targetPen.fromLeft < targetPen.fromRight ? targetPen.fromLeft : targetPen.fromRight,
    targetPen.fromTop < targetPen.fromBottom ? targetPen.fromTop : targetPen.fromBottom
  );
  for (let i = 1; i < hits.length; i++) {
    const pen = facePenetrations(ball, hits[i]);
    const approaching = isApproaching(ball, pen);
    const depth = Math.min(
      pen.fromLeft < pen.fromRight ? pen.fromLeft : pen.fromRight,
      pen.fromTop < pen.fromBottom ? pen.fromTop : pen.fromBottom
    );
    if (approaching !== targetApproach) {
      // Approaching hits always beat grazing ones.
      if (approaching) {
        target = hits[i];
        targetPen = pen;
        targetApproach = true;
        targetDepth = depth;
      }
    } else if (depth < targetDepth) {
      target = hits[i];
      targetPen = pen;
      targetDepth = depth;
    }
  }

  resolveBrick(state, ball, target);
  for (const brick of hits) {
    if (brick !== target && brick.alive) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. The motion is sub-stepped so a fast
// ball cannot tunnel through a brick row (see #1).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const dist = Math.hypot(ball.vx, ball.vy) * dt;
  const subSteps = Math.max(1, Math.ceil(dist / MAX_SUB_STEP));
  const subDt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    breakBricks(state);

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {

